query m_reset() {
  delete Entry where true
  delete Task where true
  delete Agent where true
  delete Skill where true
}

query m_fixture_base($task_id: String, $skill_id: String) {
  insert Skill { id: $skill_id }
  insert Task { id: $task_id, state: "open" }
  insert Needs { from: $task_id, to: $skill_id }
  insert Entry {
    id: "entry-0",
    seq: 0,
    rule: "genesis",
    hash: "0",
    prev: "",
    ts: 0
  }
}

query m_fixture_agent($agent_id: String, $skill_id: String) {
  insert Agent { id: $agent_id }
  insert HasSkill { from: $agent_id, to: $skill_id }
}

query q_task($task_id: String) {
  match {
    $task: Task { id: $task_id }
  }
  return { $task.id as task, $task.state as state }
}

query q_task($task_id: String) {
  match {
    $task: Task { id: $task_id }
  }
  return { $task.id as task, $task.state as state }
}

query q_task_holder($task_id: String) {
  match {
    $task: Task { id: $task_id }
    $task $lease:heldBy $holder
  }
  return {
    $holder.id as holder,
    $lease.from_seq as from_seq,
    $lease.rw as rw
  }
  order { holder asc }
}

