query q_task_holder($task_id: String) {
  match {
    $task: Task { id: $task_id }
    $task $lease:heldBy $holder
  }
  return {
    $holder.id as holder,
    $lease.from_seq as from_seq,
    $lease.rw as rw
  }
  order { holder asc }
}

